 const add=(t,h,b)=>{const n=L[t]||(L[t]={overview:'',sections:[],questions:[],revision:''}); n.sections=Array.isArray(n.sections)?n.sections:[]; if(!n.sections.some(x=>x[0]===h)) n.sections.push([h,b]); n.longForm=true;};
 Object.keys(M).forEach(t=>{
   const [core,steps,formula,app]=M[t];
   add(t,'Detailed Concept and Scope',`<p><b>Core idea:</b> ${core}. This topic should be understood as a connected chain of ideas, not as a definition to memorize. Start by identifying the main quantity, object, process or principle described by the topic. Then connect each new term to the previous one and keep units, conditions and assumptions visible.</p><p><b>Why it matters:</b> ${app}. In examination answers, the explanation should establish the principle first and then show how the principle is used. In practical work, the same concept becomes useful only when the correct instrument, boundary condition, material or procedure is selected.</p>`);
   add(t,'Step-by-Step Learning Method',`<p>${steps}. A reliable study sequence is: (1) write the definition in your own words, (2) identify the quantities or components involved, (3) draw the relevant diagram or flow, (4) state the governing relation, (5) work one example, and (6) check the result against units, direction, dimensions or expected behavior.</p><p>Do not skip the conditions under which a rule applies. Many wrong answers come from using a correct formula in the wrong physical or mathematical situation.</p>`);
   add(t,'Formula, Principle or Rule Explained',`<p><b>Core relation:</b> ${formula}. Every symbol in a formula represents a measurable quantity, mathematical variable or defined condition. Write the meaning and unit beside symbols before substituting numerical values. If the topic is descriptive rather than numerical, the “core relation” should be treated as its governing principle, process sequence or classification rule.</p><p>After calculation, perform a sanity check: is the sign reasonable, is the magnitude plausible, and are the units consistent? This habit is especially important in engineering numericals.</p>`);
   add(t,'Worked Example / Application',`<p><b>Engineering application:</b> ${app}. A useful example should begin with a stated situation, identify known and unknown quantities, choose the relevant principle, substitute carefully and finish with a unit-bearing answer or clearly stated conclusion.</p><ol><li>Read the problem and list the given information.</li><li>Identify what is required.</li><li>Draw a simple labelled representation where useful.</li><li>Select the governing concept or equation.</li><li>Substitute values step by step.</li><li>Check the result and state the final answer clearly.</li></ol>`);
   add(t,'Common Errors and Examination Points',`<p>Typical mistakes include memorising a formula without understanding its conditions, mixing units, skipping a diagram, using an incorrect sign convention, confusing similar terms, or writing a final numerical value without a unit. For theory answers, marks are easier to earn when the response contains <b>definition → principle → explanation → diagram/process → application</b> rather than a single sentence.</p><p><b>Exam focus:</b> prepare the definition, one labelled figure or flowchart, the principal formula/rule, one worked example and at least two application-based questions for this topic.</p>`);
   add(t,'Deep Revision Map',`<p><b>Remember:</b> ${core}. <b>Connect it with:</b> ${app}. Before moving to the next topic, you should be able to explain the idea without looking at the note, reproduce the important diagram or process, state the governing relation, and solve or discuss one representative problem.</p><p><b>Self-check:</b> What is the definition? What are the important parts/variables? Why does the process work? What changes when a condition changes? Where is it used? What is one limitation or common error?</p>`);
 });
